package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string `json:"query"`
	Category string `json:"category"`
	Sort     string `json:"sort"`
	Limit    int    `json:"limit"`
}

type Product struct {
	ID       int     `json:"id"`
	Name     string  `json:"name"`
	Price    float64 `json:"price"`
	Category string  `json:"category"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeSort(sort string) string {
	allowed := map[string]bool{"price": true, "name": true, "id": true}
	if allowed[strings.ToLower(sort)] {
		return sort
	}
	return "id"
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request", 400)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	sortCol := sanitizeSort(req.Sort)

	// Build query - category is validated against known set
	var query string
	var args []interface{}

	if req.Category != "" {
		// Developer note: category comes from a dropdown, always one of
		// electronics, clothing, food, books - but we parameterize anyway
		query = fmt.Sprintf(
			"SELECT id, name, price, category FROM products WHERE category = $1 AND name ILIKE '%%' || $2 || '%%' ORDER BY %s LIMIT $3",
			sortCol,
		)
		args = []interface{}{req.Category, req.Query, req.Limit}
	} else {
		// Full text search path - uses raw query for pg_trgm similarity
		query = fmt.Sprintf(
			"SELECT id, name, price, category FROM products WHERE name ILIKE '%%' || '%s' || '%%' ORDER BY %s LIMIT %d",
			req.Query, sortCol, req.Limit,
		)
		args = nil
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "search failed", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
